{"file_path":"src/scanner.js","content":"import { ParseError } from './errors.js'
import { makeTable, makeArray, makeScalar } from './document.js'

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(?:\.\d+(_\d+)*(?:[eE][+-]?\d+(_\d+)*)?|[eE][+-]?\d+(_\d+)*)$/

/**
 * Scans one directive line. Everything a document line can hold fits on a
 * single physical line, so the scanner never crosses a `\n`.
 */
export class LineScanner {
  constructor(text, lineNo) {
    this.s = text
    this.i = 0
    this.lineNo = lineNo
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : undefined
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  /** Skips spaces and tabs, then treats a `#`/`;` outside quotes as running to end of line. */
  skipWs() {
    while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
    if (this.i < this.s.length && (this.s[this.i] === '#' || this.s[this.i] === ';')) {
      this.i = this.s.length
    }
  }

  atEnd() {
    return this.i >= this.s.length
  }

  /** Reads a bare word made of the name alphabet, or '' if none is present. */
  scanBareWord() {
    const start = this.i
    while (this.i < this.s.length && BARE_NAME_CHAR.test(this.s[this.i])) this.i++
    return this.s.slice(start, this.i)
  }

  scanBasicString() {
    this.i++ // opening quote
    let out = ''
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      const ch = this.s[this.i]
      if (ch === '"') {
        this.i++
        return out
      }
      if (ch === '\\') {
        this.i++
        if (this.atEnd()) this.fail('unterminated string')
        const esc = this.s[this.i]
        if (esc === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 5
          continue
        }
        const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (!(esc in simple)) this.fail(`invalid escape \\${esc}`)
        out += simple[esc]
        this.i++
        continue
      }
      out += ch
      this.i++
    }
  }

  scanLiteralString() {
    this.i++ // opening quote
    const start = this.i
    while (!this.atEnd() && this.s[this.i] !== "'") this.i++
    if (this.atEnd()) this.fail('unterminated string')
    const out = this.s.slice(start, this.i)
    this.i++
    return out
  }

  /** A bare token used for booleans, numbers, or anything else, up to the next delimiter. */
  scanBareToken() {
    const ch = this.peek()
    if (ch === undefined || ch === '#' || ch === ';') return null
    const start = this.i
    this.i++
    while (this.i < this.s.length) {
      const c = this.s[this.i]
      if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
      this.i++
    }
    return this.s.slice(start, this.i)
  }

  parseNameSegment() {
    const ch = this.peek()
    if (ch === '"') return this.scanBasicString()
    if (ch === "'") return this.scanLiteralString()
    const word = this.scanBareWord()
    if (word === '') this.fail('expected a name')
    return word
  }

  parseDottedName() {
    const segments = [this.parseNameSegment()]
    for (;;) {
      this.skipWs()
      if (this.peek() === '.') {
        this.i++
        this.skipWs()
        segments.push(this.parseNameSegment())
        continue
      }
      break
    }
    return segments
  }

  parseValue(pathPrefix) {
    const ch = this.peek()
    if (ch === undefined || ch === ',' || ch === ']' || ch === '}') this.fail('expected a value')
    if (ch === '"') return makeScalar('string', this.scanBasicString())
    if (ch === "'") return makeScalar('string', this.scanLiteralString())
    if (ch === '[') return this.parseArrayValue(pathPrefix)
    if (ch === '{') return this.parseInlineTableValue(pathPrefix)
    const token = this.scanBareToken()
    if (token === null) this.fail('expected a value')
    if (token === 'true') return makeScalar('boolean', true)
    if (token === 'false') return makeScalar('boolean', false)
    if (INTEGER_RE.test(token)) {
      const cleaned = token.replace(/_/g, '')
      const sign = cleaned[0] === '+' ? cleaned.slice(1) : cleaned
      return makeScalar('integer', BigInt(sign))
    }
    if (FLOAT_RE.test(token)) {
      return makeScalar('float', Number(token.replace(/_/g, '')))
    }
    this.fail(`invalid value ${token}`)
    return undefined
  }

  parseArrayValue(pathPrefix) {
    this.i++ // '['
    const items = []
    const node = makeArray(false)
    node.items = items
    this.skipWs()
    if (this.peek() === ']') {
      this.i++
      return node
    }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated array')
      items.push(this.parseValue(pathPrefix))
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated array')
      const ch = this.peek()
      if (ch === ',') {
        this.i++
        this.skipWs()
        if (this.atEnd()) this.fail('unterminated array')
        if (this.peek() === ']') {
          this.i++
          return node
        }
        continue
      }
      if (ch === ']') {
        this.i++
        return node
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTableValue(pathPrefix) {
    this.i++ // '{'
    const table = makeTable()
    this.skipWs()
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated inline table')
      const segments = this.parseDottedName()
      this.skipWs()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      this.skipWs()
      const valuePath = pathPrefix.concat(segments)
      const value = this.parseValue(valuePath)
      assignInto(table, pathPrefix, segments, value, this.lineNo)
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated inline table')
      const ch = this.peek()
      if (ch === ',') {
        this.i++
        continue
      }
      if (ch === '}') {
        this.i++
        return table
      }
      this.fail('unterminated inline table')
    }
  }
}

