export function makeTable() {
  return { type: 'table', map: new Map(), headerOpened: false }
}

export function makeArray(isTableArray) {
  return { type: 'array', items: [], isTableArray }
}

export function makeScalar(type, value) {
  return { type, value }
}

/** The document under construction: its root table and the table new keys land in. */
export class Document {
  constructor() {
    this.root = makeTable()
    this.currentTable = this.root
    this.currentTablePath = []
  }
}

/**
 * Moves from `current` into the table named `name`, creating it if absent.
 * `pathSoFar` already includes `name` and is used to phrase the error.
 */
function descend(current, name, pathSoFar, lineNo) {
  const existing = current.map.get(name)
  if (existing === undefined) {
    const table = makeTable()
    current.map.set(name, table)
    return table
  }
  if (existing.type === 'table') return existing
  if (existing.type === 'array' && existing.isTableArray) return existing.items[existing.items.length - 1]
  throw new ParseError(lineNo, `${pathSoFar.join('.')} is not a table`)
}

/** Assigns `segments` (a dotted key) to `value` inside `baseTable`, creating tables along the way. */
export function assignInto(baseTable, basePath, segments, value, lineNo) {
  let current = baseTable
  const pathAcc = basePath.slice()
  for (let idx = 0; idx < segments.length - 1; idx++) {
    pathAcc.push(segments[idx])
    current = descend(current, segments[idx], pathAcc, lineNo)
  }
  const last = segments[segments.length - 1]
  pathAcc.push(last)
  if (current.map.has(last)) throw new ParseError(lineNo, `key ${pathAcc.join('.')} is defined twice`)
  current.map.set(last, value)
}

/** Handles a `[name]` header: creates/opens the named table and makes it current. */
export function openTableHeader(document, segments, lineNo) {
  let current = document.root
  const pathAcc = []
  for (let idx = 0; idx < segments.length - 1; idx++) {
    pathAcc.push(segments[idx])
    current = descend(current, segments[idx], pathAcc, lineNo)
  }
  const last = segments[segments.length - 1]
  pathAcc.push(last)
  const fullPath = pathAcc.join('.')
  const existing = current.map.get(last)
  if (existing === undefined) {
    const table = makeTable()
    table.headerOpened = true
    current.map.set(last, table)
    document.currentTable = table
    document.currentTablePath = pathAcc
    return
  }
  if (existing.type !== 'table') throw new ParseError(lineNo, `${fullPath} is not a table`)
  if (existing.headerOpened) throw new ParseError(lineNo, `table ${fullPath} is defined twice`)
  existing.headerOpened = true
  document.currentTable = existing
  document.currentTablePath = pathAcc
}

/** Handles a `[[name]]` header: appends a fresh table to the array of tables and makes it current. */
export function openArrayTableHeader(document, segments, lineNo) {
  let current = document.root
  const pathAcc = []
  for (let idx = 0; idx < segments.length - 1; idx++) {
    pathAcc.push(segments[idx])
    current = descend(current, segments[idx], pathAcc, lineNo)
  }
  const last = segments[segments.length - 1]
  pathAcc.push(last)
  const fullPath = pathAcc.join('.')
  let existing = current.map.get(last)
  if (existing === undefined) {
    existing = makeArray(true)
    current.map.set(last, existing)
  } else if (!(existing.type === 'array' && existing.isTableArray)) {
    throw new ParseError(lineNo, `${fullPath} is not an array of tables`)
  }
  const table = makeTable()
  existing.items.push(table)
  document.currentTable = table
  document.currentTablePath = pathAcc
}
