{"file_path":"src/parser.js","content":"import { ParseError } from './errors.js'
import { LineScanner } from './scanner.js'
import { Document, assignInto, openTableHeader, openArrayTableHeader } from './document.js'

/** Parses a whole configuration document and returns its root table node. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const document = new Document()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const scanner = new LineScanner(lines[idx], lineNo)
    scanner.skipWs()
    if (scanner.atEnd()) continue // blank or comment-only line

    if (scanner.peek() === '[') {
      parseHeaderLine(scanner, document)
    } else {
      parseAssignmentLine(scanner, document)
    }
  }

  return document.root
}

function parseHeaderLine(scanner, document) {
  scanner.i++ // '['
  let isArray = false
  if (scanner.peek() === '[') {
    isArray = true
    scanner.i++
  }
  scanner.skipWs()
  if (scanner.atEnd()) scanner.fail('unterminated table header')
  const segments = scanner.parseDottedName()
  scanner.skipWs()
  if (scanner.atEnd()) scanner.fail('unterminated table header')
  if (scanner.peek() !== ']') scanner.fail('unterminated table header')
  scanner.i++
  if (isArray) {
    if (scanner.peek() !== ']') scanner.fail('unterminated table header')
    scanner.i++
  }
  scanner.skipWs()
  if (!scanner.atEnd()) scanner.fail('trailing text after a table header')

  if (isArray) openArrayTableHeader(document, segments, scanner.lineNo)
  else openTableHeader(document, segments, scanner.lineNo)
}

function parseAssignmentLine(scanner, document) {
  const segments = scanner.parseDottedName()
  scanner.skipWs()
  if (scanner.peek() !== '=') scanner.fail('expected key = value')
  scanner.i++
  scanner.skipWs()
  const valuePath = document.currentTablePath.concat(segments)
  const value = scanner.parseValue(valuePath)
  scanner.skipWs()
  if (!scanner.atEnd()) scanner.fail('trailing text after a value')
  assignInto(document.currentTable, document.currentTablePath, segments, value, scanner.lineNo)
}

export { ParseError }
"}

