{"file_path":"src/format.js","content":"function sortedKeys(map) {
  return Array.from(map.keys()).sort()
}

function jsonValue(node, level) {
  const indent = '  '.repeat(level)
  const childIndent = '  '.repeat(level + 1)
  switch (node.type) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const members = keys.map((k) => `${childIndent}${JSON.stringify(k)}: ${jsonValue(node.map.get(k), level + 1)}`)
      return `{\n${members.join(',\n')}\n${indent}}`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const items = node.items.map((v) => `${childIndent}${jsonValue(v, level + 1)}`)
      return `[\n${items.join(',\n')}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
}

/** Renders the document as canonical JSON, indented by two spaces, with a trailing newline. */
export function toJSON(root) {
  return `${jsonValue(root, 0)}\n`
}

function typeOf(node) {
  return node.type
}

function walk(node, path, out) {
  if (node.type === 'table') {
    for (const key of sortedKeys(node.map)) {
      const childPath = path ? `${path}.${key}` : key
      const child = node.map.get(key)
      out.push(`${childPath} ${typeOf(child)}`)
      walk(child, childPath, out)
    }
  } else if (node.type === 'array') {
    node.items.forEach((item, idx) => {
      const childPath = `${path}[${idx}]`
      out.push(`${childPath} ${typeOf(item)}`)
      walk(item, childPath, out)
    })
  }
}

/** Renders one `<path> <type>` line per node below the root, depth first. */
export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

